      // typed char — masking held from the first keystroke through the
      // last. The history's tool row (`• request_secret · …`) is not
      // frame-closed, so the `│` guard pins this to the sheet's own row.
      final row = maskedValueRow(screen);
      if (row == null) {
        throw StateError(
